face.layout_source:
// radio-voice.face: the panel for tap/examples/graphs/radio-voice.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/graphs/radio-voice.face --meta <graph>.cragmeta

face "Radio Voice" {
  row(gap = 10) {
    box "Voice" (grow = 1) {
      knob "Threshold" (tight.threshold) knob "Ratio" (tight.ratio) knob "Attack" (tight.attack) knob "Release" (tight.release)
    }
    box "Bus" (grow = 1) {
      knob "Threshold" (level.threshold) knob "Ratio" (level.ratio) knob "Attack" (level.attack) knob "Release" (level.release)
    }
  }
  box "Music Bed" {
    knob.big "Threshold" (ducker.threshold) knob "Ratio" (duck_ratio) knob "Attack" (bed.attack) knob "Release" (bed.release)
    bar "Duck" (ducking)
  }
}
